mapper.select:
select A.record_id, A.owner_uid, A.pet_uid, A.adopt_date, A.state, A.create_by, A.create_by_name, A.create_time, A.update_by, A.update_by_name, A.update_time, B.username as owner_name, C.nickname as pet_name, C.photo as pet_photo, C.breed as pet_breed, C.gender as pet_gender, C.years as pet_years, C.health_condition as pet_health, C.introduction as pet_intro from adoption_record as A left join user as B on (A.owner_uid=B.id) left join adoptable_pet as C on (A.pet_uid=C.pid)
and C.breed = #{breed}
and A.state = #{state}
order by A.record_id desc
